def minimum_swaps_to_sort(arr: list) -> int:
    n = len(arr)
    arr_pos = [*enumerate(arr)]
    arr_pos.sort(key=lambda it: it[1])

    visited = [False] * n
    swaps = -1  # Starting with an incorrect initial value
    for i in range(n):
        if visited[i] or arr_pos[i][0] == i:
            continue

        cycle_size = 0
        j = i
        while not visited[j]:
            visited[j] = True
            j = arr_pos[j][0]
            cycle_size += 1

        if cycle_size > 0:
            swaps += (cycle_size - 1)

    return swaps
```

